import { CustomPageStore } from '@/components/CustomPage';
import { ApiPageData } from '@/types/page';
import { moduleStore } from 'react-converter-code';
import { getMenuList  } from '@/api';
import { IRoute } from "@/types/route"
import { MenuItem } from '@/types/menu';
import { action, makeObservable, observable } from 'mobx';

class PageStore {

    @observable current = null;
    @action setCurrent = (uid) => {
        this.current = uid;
    }

    oldPages:Record<string, CustomPageStore> = {};

    /**
     * 存储模块信息(所有编辑模块)
     */
    pages: Record<string, CustomPageStore> = {};


    menus: MenuItem[] = []
    /**
     * 获取所有菜单
     */
    getMenuList = async () => {
        return this.menus = await getMenuList({});
    }
    
    /**
     * 重置store
     */
    reset(){
        this.oldPages = this.pages;
        this.pages = {};
    }
    
    async addTabPage(item: ApiPageData) {
        if(this.pages[item.id]) {
            const store = this.pages[item.id]
            store.name = item.title;
            return store;
        };
        if(this.oldPages[item.id]){
            this.pages[item.id] = this.oldPages[item.id];
            const store = this.pages[item.id]
            store.name = item.title;
            return store;
        }
        const { id, title } = item;
        const pageStore = new CustomPageStore({
            uid: id,
            name: title,
        });
        const extraInfo = item.extraInfo? JSON.parse(item.extraInfo) :  "";
        const content = item.content? JSON.parse(item.content as any) : "";
        if(extraInfo){
            if(extraInfo.components) await moduleStore.syncModuleIds(extraInfo.components)
            pageStore.previewImg = extraInfo?.previewImg;
        }
        if(content) pageStore.setData(content);
        this.pages[id] = pageStore;
        return pageStore;
    }


    constructor(){
        makeObservable(this);
    }

}


export default new PageStore();